(() => {
 const local=['localhost','127.0.0.1'].includes(location.hostname);
 const a={loaded:false,loading:false,token:'',capabilities:null,queue:[],jobs:[],selected:null,mode:'production',busy:false,error:'',publishResult:null,timer:null};
 const active=j=>j&&['queued','generating','validating'].includes(j.status);
 const labels={queued:'准备中',generating:'正在生成',validating:'逐页验收',ready:'图文已就绪',failed:'需要处理',interrupted:'已中断',cancelled:'已停止'};
 names.atlas='拾光百科';
 const nav=document.createElement('button');nav.className='nav-item';nav.dataset.nav='atlas';nav.innerHTML=icon('spark')+'<span>拾光百科</span><span class="atlas-new">NEW</span>';
 document.querySelector('.sidebar nav').insertBefore(nav,document.querySelector('.sidebar nav .nav-separator'));
 const baseRender=render;
 render=function(){baseRender();clearTimeout(a.timer);if(state.page==='atlas'){paint();if(local&&!a.loading)load();}else if(state.page==='dashboard'){
  const btn=document.querySelector('.hero [data-action="create"]');if(btn){delete btn.dataset.action;btn.dataset.nav='atlas';btn.innerHTML='生成今日图文 '+icon('arrow')}
  document.querySelector('.hero-copy p').innerHTML='拾光百科已接入。把一个选题，<br>变成可预览、可发布的完整图文。';
  document.querySelector('.hero-copy small').textContent='Codex 内置生图 · 本机保存';
 }};
 async function api(url,body){const options=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Orbit-Token':a.token},body:JSON.stringify(body)};const response=await fetch(url,options);const result=await response.json();if(!response.ok)throw new Error(result.error||'操作未完成');return result}
 async function load(){if(a.loading)return;a.loading=true;try{const b=await api('/api/bootstrap');a.token=b.token;a.capabilities=b.capabilities;a.queue=b.queue;a.jobs=b.jobs;const running=a.jobs.find(active);if(running)a.mode=running.mode;if(!a.selected)a.selected=a.jobs[0]?.id||null;a.loaded=true;a.error='';document.querySelector('.live').innerHTML='<i></i>本机创作空间';}catch(e){a.error='连接本地服务失败，请运行项目中的“启动工作台.cmd”。'+e.message;}finally{a.loading=false;if(state.page==='atlas'){paint();poll()}}}
 function selected(){return a.jobs.find(j=>j.id===a.selected)}
 function upsert(job){const i=a.jobs.findIndex(j=>j.id===job.id);if(i<0)a.jobs.unshift(job);else a.jobs[i]=job;a.selected=job.id}
 function poll(){clearTimeout(a.timer);if(state.page!=='atlas')return;const job=selected();if(!active(job))return;a.timer=setTimeout(async()=>{try{upsert(await api('/api/jobs/'+job.id));paint()}catch(e){a.error='进度连接暂时中断：'+e.message;paint()}poll()},3000)}
 function top(){return `<div class="page-heading atlas-heading"><div><div class="eyebrow">SHIGUANG ATLAS / CREATIVE STUDIO</div><h1>把知识，变成值得收藏的图文。</h1><p>选题、文案、参考图生图与发布准备，在一个地方完成。</p></div><button class="btn" data-atlas="refresh" ${a.busy?'disabled':''}>${icon('layers')}刷新状态</button></div>`}
 function offline(){return `<section class="panel atlas-offline"><div class="atlas-orb">${icon('spark')}</div><h2>让本机工作台接手创作</h2><p>生成需要调用你电脑上已登录的 Codex，发布准备需要打开文件和剪贴板。<br>请双击项目中的 <strong>启动工作台.cmd</strong>，然后进入本机工作台。</p><a class="btn btn-primary" href="http://127.0.0.1:4173/#atlas">打开本机工作台 ${icon('arrow')}</a><p class="atlas-fine">图片与文案保存在你的电脑。此在线预览不会远程操作电脑。</p></section>`}
 function paint(){if(state.page!=='atlas')return;const content=document.querySelector('#content');if(!local){content.innerHTML=top()+offline();return}if(!a.loaded){content.innerHTML=top()+`<div class="notice-box">${a.error?esc(a.error):'正在检查本机 Codex 登录状态与生成环境…'}</div>`;return}
 const job=selected(),pending=a.queue.filter(q=>q.status==='TODO'),running=a.jobs.find(active),caps=a.capabilities;
 content.innerHTML=top()+`<div class="atlas-connection"><span><i class="connected-dot"></i>${caps.available?'Codex 已就绪':'生成环境尚未就绪'}</span><span>ChatGPT 登录 · 内置 GPT 生图</span><span>本机保存</span></div>${!caps.available?`<div class="atlas-error" role="alert">${esc(caps.reason)}</div>`:''}${a.error?`<div class="atlas-error" role="alert">${esc(a.error)}</div>`:''}
 <div class="atlas-grid"><section class="atlas-launch panel"><div class="section-top"><span class="eyebrow">TODAY'S CREATION</span><span class="atlas-date mono">${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'}).format(new Date())}</span></div><div class="atlas-topic-label">${job?'当前创作':'下一份灵感'}</div><h2>${esc(job?.topic||pending[0]?.topic||'主题队列已完成')}</h2><p>遵循拾光百科的博物志风格，基于真实参考图制作封面、知识内页与完整小红书文案。</p><div class="atlas-specs"><span>米黄旧纸 · 百科插画</span><span>3:4 竖版 · 提示词要求</span><span>逐页质检</span></div><div class="atlas-launch-actions"><button class="btn btn-primary" data-atlas="generate" ${a.busy||running||!caps.available||!pending.length?'disabled':''}>${icon('spark')}${running?'正在为你创作…':'生成今日图文'}</button><label class="atlas-mode">运行模式 <select id="atlas-mode" ${a.busy||running?'disabled':''}><option value="production" ${a.mode==='production'?'selected':''}>正式生成</option><option value="test" ${a.mode==='test'?'selected':''}>独立测试</option></select></label></div><div class="atlas-fine">${a.mode==='test'?'使用隔离队列副本，不修改正式进度。':'读取首条待办，每天一篇；失败继续原主题，成功才推进队列。'} 生成期间保持本地服务运行。</div></section>
 <section class="panel atlas-queue"><div class="section-top"><h2>灵感正在排队</h2><span class="muted">${pending.length} 个待办</span></div>${pending.slice(0,4).map((q,i)=>`<div class="atlas-topic-row"><span class="mono">0${i+1}</span><div>${esc(q.topic)}<small>${esc(q.category)}</small></div>${i===0?'<span class="atlas-next">NEXT</span>':''}</div>`).join('')}<p class="atlas-fine">首次从 Skill 附带主题快照初始化，保留原有进度。之后使用本机最新队列。</p></section></div>
 <div class="section-heading atlas-results-heading"><h2>创作成果 <span>${job?job.mode==='test'?'独立测试 · 正式队列未推进':'正式内容':'等待第一份灵感'}</span></h2>${a.jobs.length?`<label class="atlas-history">历史任务 <select id="atlas-history" aria-label="历史任务">${a.jobs.map(j=>`<option value="${j.id}" ${j.id===a.selected?'selected':''}>${esc(j.topic)} · ${j.mode==='test'?'测试':'正式'} · ${labels[j.status]}</option>`).join('')}</select></label>`:''}</div>
 ${job?jobView(job):`<section class="panel atlas-empty"><div class="atlas-empty-icon">${icon('image')}</div><h3>你的下一篇百科，正在等你开启</h3><p>点击“生成今日图文”，这里会出现封面、全部内页和文案。<br>素材齐备并通过验收后，即可一键准备发布。</p><div class="atlas-steps"><span>01 选题与查证</span><i>→</i><span>02 图文生成</span><i>→</i><span>03 质检与发布</span></div></section>`}
 <footer class="footer"><span><i class="connected-dot"></i> ORBIT × 拾光百科</span><span>内置生图 · 原始文件保存 · 最终发布由你确认</span></footer>`;
 }
 function jobView(j){const ready=j.ready,retry=['failed','interrupted','cancelled'].includes(j.status);return `<section class="panel atlas-job"><div class="atlas-job-top"><div><span class="atlas-state ${ready?'is-ready':retry?'is-error':'is-running'}"><i></i>${labels[j.status]}</span><span class="atlas-job-count">${j.images.length}${j.expectedImages?' / '+j.expectedImages:''} 张图片</span></div><div class="atlas-job-actions">${['queued','generating'].includes(j.status)?'<button class="btn" data-atlas="cancel">停止生成</button>':''}${retry?'<button class="btn" data-atlas="retry">继续生成</button>':''}<button class="btn" data-atlas="folder">${icon('image')}打开文件夹</button><button class="btn btn-primary" data-atlas="publish" ${!ready||a.busy?'disabled':''}>${icon('send')}一键发布</button></div></div><div class="atlas-progress-message" role="status">${esc(j.message)}</div>
 ${a.publishResult?`<div class="atlas-publish-guide"><strong>发布材料已准备</strong><p>${['browser','folder','caption','preview','clipboard'].map((key,i)=>`${a.publishResult[key]?'✓':'未完成：'} ${['小红书页面','素材文件夹','文案窗口','封面预览','图片路径复制'][i]}`).join(' · ')}</p><ol><li>在小红书选择“上传图文”，点上传图片，在文件选择窗口按 <kbd>Ctrl + V</kbd>、回车。</li><li>点击下方“复制标题”“复制正文”，粘贴到对应位置。图片路径可随时重新复制。</li><li>检查内容和平台提示，在小红书完成最终发布。</li></ol><small>若浏览器未打开，可<a href="https://creator.xiaohongshu.com/publish/publish?source=official&target=image" target="_blank" rel="noopener">直接进入小红书创作中心 ↗</a>。本工作台不会代点最终发布。</small></div>`:''}
 <div class="atlas-delivery"><div><div class="atlas-section-label">图片素材 <span>封面在前，内页按编号排列</span></div><div class="atlas-gallery">${j.images.length?j.images.map((im,i)=>`<button class="atlas-image" data-atlas-image="${esc(im.url)}" data-title="${esc(im.name)}"><img src="${esc(im.url)}" alt="${esc(im.name)}" loading="lazy"><span>${i===0?'封面':String(i).padStart(2,'0')}<small>${im.dimensions?im.dimensions.width+' × '+im.dimensions.height:'待测量'}</small></span></button>`).join(''):Array.from({length:5},(_,i)=>`<div class="atlas-image skeleton"><div>${icon(i?'file':'image')}</div><span>${i===0?'封面':'内容页 '+i}</span></div>`).join('')}</div><div class="atlas-image-actions"><button class="btn" data-atlas="paths" ${!ready||a.busy?'disabled':''}>${icon('link')}复制全部图片路径</button><span class="atlas-fine">强要求 1086×1448；显示原生实际尺寸，不缩放裁切。</span></div></div><div class="atlas-copy"><div class="atlas-section-label">小红书文案 <span>${j.caption?j.caption.body.length+' 字':'等待生成'}</span></div><div class="atlas-copy-head"><h3>${esc(j.caption?.title||'好故事，从一个好问题开始')}</h3><button data-atlas="title" ${!ready||a.busy?'disabled':''}>复制标题</button></div><div class="atlas-copy-body">${esc(j.caption?.body||'Codex 完成来源查证后，会在这里呈现完整正文和话题标签。')}</div><button class="btn" data-atlas="body" ${!ready||a.busy?'disabled':''}>${icon('file')}复制正文与标签</button></div></div>
 <details class="atlas-log" ${retry?'open':''}><summary>生成记录与保存位置</summary><p class="atlas-path">${esc(j.project)}</p>${j.events.slice(-12).reverse().map(e=>`<div><time>${new Date(e.time).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</time><span>${esc(e.message)}</span></div>`).join('')}</details></section>`}
 document.addEventListener('change',e=>{if(e.target.id==='atlas-mode'){a.mode=e.target.value;paint()}if(e.target.id==='atlas-history'){a.selected=e.target.value;a.publishResult=null;paint();poll()}});
 document.addEventListener('click',async e=>{const imageButton=e.target.closest('[data-atlas-image]');if(imageButton){const d=document.createElement('dialog');d.className='atlas-preview';d.innerHTML=`<div class="dialog-header"><h2>${esc(imageButton.dataset.title)}</h2><button aria-label="关闭图片">${icon('close')}</button></div><img src="${esc(imageButton.dataset.atlasImage)}" alt="${esc(imageButton.dataset.title)}">`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();return}
 const btn=e.target.closest('[data-atlas]');if(!btn||a.busy)return;const action=btn.dataset.atlas;if(action==='refresh'){await load();return}a.busy=true;a.error='';const j=selected();paint();try{switch(action){case 'generate':upsert(await api('/api/jobs',{mode:a.mode}));a.publishResult=null;break;case 'retry':upsert(await api(`/api/jobs/${j.id}/retry`,{}));break;case 'cancel':upsert(await api(`/api/jobs/${j.id}/cancel`,{}));break;case 'folder':await api(`/api/jobs/${j.id}/open-folder`,{});toast('已打开素材文件夹');break;case 'publish':a.publishResult=await api(`/api/jobs/${j.id}/publish`,{});toast(a.publishResult.clipboard?'图片路径已复制，按页面提示继续发布。':'部分准备操作未完成，请查看详情。');break;case 'title':case 'body':case 'paths':await api(`/api/jobs/${j.id}/copy`,{kind:action});toast({title:'标题已复制',body:'正文与标签已复制',paths:'图片路径已按发布顺序复制'}[action]);break}}catch(err){a.error=err.message}finally{a.busy=false;paint();poll()}});
 if(location.hash==='#atlas')state.page='atlas';render();
})();
